<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {http,dataOf} from '../api/http';import {ElMessage,ElMessageBox} from 'element-plus';import {useAuthStore} from '../stores/auth';
const auth=useAuthStore(),rows=ref<any[]>([]),loading=ref(false),selected=ref<any|null>(null),measurements=ref<any[]>([]),keyword=ref(''),dialog=ref(false),operating=ref(false),governanceOptions=ref<any>({dictionaries:[],dictionaryItems:[]})
const protocolOptions=computed(()=>{const dictionary=governanceOptions.value.dictionaries.find((v:any)=>v.code==='DEVICE_PROTOCOL');return governanceOptions.value.dictionaryItems.filter((v:any)=>v.dictionaryId===dictionary?.id)})
const form=reactive({deviceCode:'',deviceName:'',deviceType:'TEST_DEVICE',model:'',protocol:'SIMULATOR',configText:'{"metricName":"temperature","baseValue":25,"amplitude":2,"unit":"C"}',dataScopeId:3})
async function load(){loading.value=true;try{const [devices,options]=await Promise.all([http.get('/devices',{params:{keyword:keyword.value}}),http.get('/governance/options')]);rows.value=dataOf(devices);governanceOptions.value=dataOf<any>(options)}finally{loading.value=false}}
async function open(row:any){selected.value=row;const page=dataOf<any>(await http.get(`/devices/${row.id}/measurements`,{params:{pageSize:100}}));measurements.value=page.list}
async function refreshSelected(){if(!selected.value)return;const row=dataOf<any>(await http.get(`/devices/${selected.value.id}`));await open(row);await load()}
async function showSecret(secret:string,title:string){await ElMessageBox.alert(`设备采集密钥（仅显示一次，请立即保存）：\n${secret}`,title,{confirmButtonText:'我已安全保存',closeOnClickModal:false,closeOnPressEscape:false})}
async function create(){let connectionConfig:any;try{connectionConfig=JSON.parse(form.configText)}catch{ElMessage.error('连接配置 JSON 格式不正确');return}operating.value=true;try{const created=dataOf<any>(await http.post('/devices',{deviceCode:form.deviceCode,deviceName:form.deviceName,deviceType:form.deviceType,model:form.model,protocol:form.protocol,connectionConfig,dataScopeId:form.dataScopeId}));dialog.value=false;await showSecret(created.deviceSecret,'设备登记成功');await load()}finally{operating.value=false}}
async function rotateSecret(){if(!selected.value)return;await ElMessageBox.confirm('轮换后旧密钥会立即失效，确认继续？','轮换采集密钥',{type:'warning'});operating.value=true;try{const result=dataOf<any>(await http.post(`/devices/${selected.value.id}/rotate-secret`));await showSecret(result.deviceSecret,'密钥已轮换')}finally{operating.value=false}}
async function setPolling(enabled:boolean){if(!selected.value)return;operating.value=true;try{await http.put(`/devices/${selected.value.id}/polling`,{enabled,intervalSeconds:selected.value.pollIntervalSeconds||5,heartbeatTimeoutSeconds:selected.value.heartbeatTimeoutSeconds||30});ElMessage.success(enabled?'模拟自动采集已启用':'自动采集已停用');await refreshSelected()}finally{operating.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><h1 class="page-title">设备与数据采集</h1><div class="page-subtitle">设备独立身份、自动采集、心跳状态与原始报文证据</div></div><el-button v-if="auth.can('device:manage')" type="primary" @click="dialog=true">登记设备</el-button></div><div class="surface toolbar"><el-input v-model="keyword" placeholder="设备名称或编码" style="width:280px" clearable @keyup.enter="load"/><el-button @click="load">查询</el-button><span class="toolbar-stat"><b>{{rows.filter(r=>r.status==='ONLINE').length}}</b> 在线 / {{rows.length}} 台</span></div><div class="device-grid" v-loading="loading"><article v-for="row in rows" :key="row.id" class="surface device" @click="open(row)"><header><div class="device-icon">⌁</div><div><el-tag v-if="row.adapterEnabled" type="primary" size="small">自动采集</el-tag> <el-tag :type="row.status==='ONLINE'?'success':'info'" size="small">{{row.status==='ONLINE'?'在线':'离线'}}</el-tag></div></header><h3>{{row.deviceName}}</h3><p class="mono">{{row.deviceCode}}</p><dl><div><dt>类型</dt><dd>{{row.deviceType}}</dd></div><div><dt>协议</dt><dd>{{row.protocol}}</dd></div><div><dt>状态原因</dt><dd>{{row.lastStatusReason||'—'}}</dd></div><div><dt>最后在线</dt><dd>{{row.lastSeenTime?String(row.lastSeenTime).slice(0,16):'尚无数据'}}</dd></div></dl></article></div><el-drawer :model-value="!!selected" :title="selected?.deviceName" size="720" @update:model-value="(value:boolean)=>{if(!value)selected=null}"><div v-if="selected" class="device-detail"><el-descriptions :column="2" border><el-descriptions-item label="设备编码">{{selected.deviceCode}}</el-descriptions-item><el-descriptions-item label="状态">{{selected.status}}</el-descriptions-item><el-descriptions-item label="类型">{{selected.deviceType}}</el-descriptions-item><el-descriptions-item label="协议">{{selected.protocol}}</el-descriptions-item><el-descriptions-item label="自动采集">{{selected.adapterEnabled?'已启用':'未启用'}}</el-descriptions-item><el-descriptions-item label="心跳阈值">{{selected.heartbeatTimeoutSeconds}} 秒</el-descriptions-item><el-descriptions-item label="状态原因" :span="2">{{selected.lastStatusReason||'—'}}</el-descriptions-item></el-descriptions><div v-if="auth.can('device:manage')" class="device-actions"><el-button :loading="operating" @click="rotateSecret">轮换设备密钥</el-button><el-button v-if="selected.protocol==='SIMULATOR'&&!selected.adapterEnabled" type="primary" :loading="operating" @click="setPolling(true)">启用模拟自动采集</el-button><el-button v-if="selected.adapterEnabled" type="warning" plain :loading="operating" @click="setPolling(false)">停用自动采集</el-button></div><el-alert v-if="selected.protocol!=='SIMULATOR'" type="info" :closable="false" title="厂商协议需完成点表、SDK/协议适配与现场联调后才可启用自动采集；当前不会将登记设备误报为已接入。"/><h3>最近测点</h3><el-table :data="measurements"><el-table-column prop="metricName" label="测点"/><el-table-column prop="metricValue" label="数值"/><el-table-column prop="unit" label="单位"/><el-table-column prop="quality" label="质量"/><el-table-column prop="sourceMode" label="来源" width="120"/><el-table-column prop="measuredTime" label="设备时间" width="180"/></el-table></div></el-drawer>
 <el-dialog v-model="dialog" title="登记设备" width="620"><el-alert type="warning" :closable="false" title="设备密钥只在登记成功时显示一次；SIMULATOR 用于验收自动采集框架，不能代表真实厂商设备已联调。"/><el-form label-position="top" style="margin-top:16px"><div class="two"><el-form-item label="设备编码"><el-input v-model="form.deviceCode"/></el-form-item><el-form-item label="设备名称"><el-input v-model="form.deviceName"/></el-form-item></div><div class="two"><el-form-item label="设备类型"><el-input v-model="form.deviceType"/></el-form-item><el-form-item label="型号"><el-input v-model="form.model"/></el-form-item></div><div class="two"><el-form-item label="协议"><el-select v-model="form.protocol" style="width:100%"><el-option v-for="option in protocolOptions" :key="option.id" :label="option.label" :value="option.value"/></el-select></el-form-item><el-form-item label="数据域"><el-input-number v-model="form.dataScopeId" :min="1"/></el-form-item></div><el-form-item label="连接配置 JSON（密码/Token 将整体 AES-GCM 加密）"><el-input v-model="form.configText" type="textarea" :rows="5" class="mono"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="operating" :disabled="!form.deviceCode||!form.deviceName" @click="create">登记</el-button></template></el-dialog>
</div></template>
<style scoped>.toolbar-stat{margin-left:auto;font-size:11px;color:#78879a}.toolbar-stat b{color:#1d8b65;font-size:16px}.device-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.device{padding:20px;cursor:pointer}.device:hover{border-color:#7daac7;transform:translateY(-1px)}.device header{display:flex;justify-content:space-between}.device-icon{width:42px;height:42px;border-radius:11px;background:#e8f3f8;color:#277593;display:grid;place-items:center;font-size:23px}.device h3{font-size:15px;margin:17px 0 5px}.device>p{font-size:10px;color:#8190a3}.device dl{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin:20px 0 0;border-top:1px solid #ebf0f4;padding-top:15px}.device dt{font-size:9px;color:#93a0af}.device dd{font-size:11px;margin:4px 0 0}.device-detail h3{margin-top:25px;font-size:14px}.device-actions{display:flex;gap:10px;margin:18px 0}.two{display:grid;grid-template-columns:1fr 1fr;gap:14px}@media(max-width:1000px){.device-grid{grid-template-columns:1fr 1fr}}@media(max-width:680px){.device-grid,.two{grid-template-columns:1fr}}</style>
